typedef struct{const void*p;size_t n;}Span;
typedef struct{CohBytes in;size_t at,end;CohStatus status;}Read;
static int valid(Span s){return s.p?(uintptr_t)s.p<=UINTPTR_MAX-s.n:!s.n;}
static int overlap(Span a,Span b){return a.n&&b.n&&(uintptr_t)a.p<(uintptr_t)b.p+b.n&&(uintptr_t)b.p<(uintptr_t)a.p+a.n;}
static uint32_t word(Read*r){if(r->status!=COH_OK)return 0;if(r->at>r->end||r->end-r->at<4){r->status=COH_INVALID;return 0;}const uint8_t*p=r->in.data+r->at;r->at+=4;return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static int finite_word(uint32_t w){return(w&UINT32_C(0x7f800000))!=UINT32_C(0x7f800000);}
static Read field(const CohClassDictionary*d,uint32_t which,unsigned index){CohClassSpan s=d->entries[which].fields[index];Read r={d->input,s.begin,s.end,COH_OK};if(s.begin>s.end||s.end>d->input.size)r.status=COH_STATE;return r;}
static CohStatus scalar(const CohClassDictionary*d,uint32_t which,unsigned index,uint32_t default_word,int required,uint32_t*out){Read r=field(d,which,index);uint32_t count=word(&r);if(r.status!=COH_OK)return r.status;if(count>1||(required&&count!=1))return COH_UNSUPPORTED;if(!count){if(r.at!=r.end)return COH_INVALID;for(unsigned j=0;j<115;j++)out[j]=default_word;return COH_OK;}uint32_t size=word(&r);if(r.status!=COH_OK||size!=460||size!=r.end-r.at)return COH_INVALID;for(unsigned j=0;j<115;j++){uint32_t w=word(&r);if(!finite_word(w))return COH_UNSUPPORTED;if(out)out[j]=w;}return r.status;}
static CohStatus table(const CohClassDictionary*d,uint32_t which,unsigned index,uint32_t level,uint32_t*out,uint32_t*levels){Read r=field(d,which,index);uint32_t count=word(&r),size=word(&r);if(r.status!=COH_OK)return r.status;if(count!=1)return COH_UNSUPPORTED;if(size!=r.end-r.at)return COH_INVALID;if(out)for(unsigned j=0;j<115;j++)out[j]=UINT32_C(0x3f800000);for(unsigned j=0;j<115;j++){uint32_t n=word(&r);if(r.status!=COH_OK)return r.status;if(n>4096)return COH_LIMIT;if(n>(r.end-r.at)/4)return COH_INVALID;if(index==28&&j==20)*levels=n;uint32_t selected=UINT32_C(0x3f800000);for(uint32_t k=0;k<n;k++){uint32_t w=word(&r);if(!finite_word(w))return COH_UNSUPPORTED;if(k<=level)selected=w;}if(out)out[attribute_order[j]]=selected;}return r.status==COH_OK&&r.at==r.end?COH_OK:COH_INVALID;}
CohStatus coh_class_level_read(const CohClassDictionary*d,const CohPowerCategoryDictionary*c,uint32_t which,uint32_t level,CohClassLevel*out,CohClassLevelWorkspace*w,size_t budget,size_t retained){
 if(!d||!c||!out||!w||!budget||budget>COH_CLASS_LEVEL_RAM_MAX)return COH_INVALID;
 Span spans[]={{d,sizeof(*d)},{c,sizeof(*c)},{out,sizeof(*out)},{w,sizeof(*w)}};size_t charged=COH_CLASS_LEVEL_STACK_RESERVE;
 for(unsigned i=0;i<4;i++){if(!valid(spans[i]))return COH_INVALID;for(unsigned j=0;j<i;j++)if(overlap(spans[i],spans[j]))return COH_INVALID;if(spans[i].n>budget||charged>budget-spans[i].n)return COH_LIMIT;charged+=spans[i].n;}
 if(!d->raw_schema_validated||!c->raw_schema_validated||!c->schema_crc_matched||!d->input_lease||!c->source_lease||d->count>COH_CLASS_MAX||which>=d->count||d->text_count>COH_CLASS_TEXTS_MAX||d->text_bytes>COH_CLASS_TEXT_BYTES_MAX||!d->input.data||!d->input.size||d->input.size>COH_CLASS_INPUT_MAX)return COH_STATE;
 Span input={d->input.data,d->input.size};if(!valid(input))return COH_INVALID;for(unsigned i=0;i<4;i++)if(overlap(input,spans[i]))return COH_INVALID;if(input.n>budget||charged>budget-input.n)return COH_LIMIT;charged+=input.n;if(retained>budget-charged)return COH_LIMIT;
 CohClassLevel*p=&w->candidate;memset(p,0,sizeof(*p));p->class_index=which;p->level=level;p->class_lease=d->input_lease;p->category_lease=c->source_lease;memcpy(p->class_sha256,d->input_sha256,32);memcpy(p->category_sha256,c->input_sha256,32);
 for(unsigned i=0;i<4;i++){CohBytes name={0};for(unsigned j=0;j<d->text_count;j++){CohClassText t=d->texts[j];if(t.owner==which&&t.table==1&&t.field==13+i){if(t.offset>=d->text_bytes||t.size>=d->text_bytes-t.offset||d->text[t.offset+t.size])return COH_STATE;name=(CohBytes){(const uint8_t*)d->text+t.offset,t.size};break;}}CohStatus status=name.size?coh_power_categories_find(c,name,&p->category_index[i]):COH_NOT_FOUND;if(status==COH_NOT_FOUND&&i>=2){const char*fallback=i==2?"Pool":"Epic";status=coh_power_categories_find(c,(CohBytes){(const uint8_t*)fallback,4},&p->category_index[i]);}if(status!=COH_OK)return status;}
 uint32_t unused[115];CohStatus status=scalar(d,which,17,0,1,unused);if(status==COH_OK)status=scalar(d,which,18,0,1,unused);if(status==COH_OK)status=scalar(d,which,19,0,0,p->attributes[4]);if(status==COH_OK)status=scalar(d,which,20,UINT32_C(0xc2c80000),0,p->attributes[5]);for(unsigned i=0;i<4&&status==COH_OK;i++)status=table(d,which,27+i,level,p->attributes[i],&p->levels);if(status!=COH_OK)return status;if(!p->levels||level>=p->levels)return COH_UNSUPPORTED;p->table_bytes=p->levels*460;p->historical_projection_validated=1;*out=*p;return COH_OK;
}
